selector_to_html = {"a[href=\"#arm64\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Arm64<a class=\"headerlink\" href=\"#arm64\" title=\"Link to this heading\">#</a></h1><h2>Overview<a class=\"headerlink\" href=\"#overview\" title=\"Link to this heading\">#</a></h2><p>Arm64 is the first fully implemented backend for TLE-CPU, targeting the Arm v9-A platform (NEON / SVE2 + i8mm + bf16), with reference hardware CIX P1 (CD8180, 8\u00d7 Cortex-A720 big cores + 4\u00d7 A520 little cores).</p><p>Software baseline: Triton 3.3 / LLVM a66376b0 / PyTorch 2.10 (CPU) / Python 3.11.</p>", "a[href=\"#data-conventions\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Data conventions<a class=\"headerlink\" href=\"#data-conventions\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">sm_scale</span></code> typically <code class=\"docutils literal notranslate\"><span class=\"pre\">head_dim^-0.5</span></code>.</p>", "a[href=\"#extension-operations-summary\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Extension Operations Summary<a class=\"headerlink\" href=\"#extension-operations-summary\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#overview\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Overview<a class=\"headerlink\" href=\"#overview\" title=\"Link to this heading\">#</a></h2><p>Arm64 is the first fully implemented backend for TLE-CPU, targeting the Arm v9-A platform (NEON / SVE2 + i8mm + bf16), with reference hardware CIX P1 (CD8180, 8\u00d7 Cortex-A720 big cores + 4\u00d7 A520 little cores).</p><p>Software baseline: Triton 3.3 / LLVM a66376b0 / PyTorch 2.10 (CPU) / Python 3.11.</p>", "a[href=\"#usage-examples\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Usage examples<a class=\"headerlink\" href=\"#usage-examples\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">rms_norm</span></code> end-to-end (<code class=\"docutils literal notranslate\"><span class=\"pre\">@triton.jit</span></code> \u2192 <code class=\"docutils literal notranslate\"><span class=\"pre\">create_cpu_rms_norm</span></code> \u2192 NEON runtime):</p>", "a[href=\"#thread-model-and-tuning\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Thread model and tuning<a class=\"headerlink\" href=\"#thread-model-and-tuning\" title=\"Link to this heading\">#</a></h3><p><strong>Thread Model</strong>: Parallelism is self-managed by the TLE runtime. In scenarios where inference is executed through torch (e.g., HF Transformers),</p><p>multi-threaded parallelism for compute-intensive parts is initiated inside the TLE runtime kernel \u2014 <code class=\"docutils literal notranslate\"><span class=\"pre\">#pragma</span> <span class=\"pre\">omp</span> <span class=\"pre\">parallel</span></code> in <code class=\"docutils literal notranslate\"><span class=\"pre\">runtime_*.cpp</span></code>, partitioned along the N dimension / head dimension \u2014 not through torch\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">at::parallel_for</span></code> or its intra-op thread pool. Two configurations ensure TLE\u2019s OMP does not contend for cores with torch:</p>", "a[href=\"#arm64-lowering-path\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Arm64 lowering path<a class=\"headerlink\" href=\"#arm64-lowering-path\" title=\"Link to this heading\">#</a></h3><p>Extension operations, after passing through the TritonCPU dialect, split into two paths based on lowering:</p>", "a[href=\"#design-essentials-dispatch-is-performance\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Design essentials: Dispatch is performance<a class=\"headerlink\" href=\"#design-essentials-dispatch-is-performance\" title=\"Link to this heading\">#</a></h2><p>The decode bottleneck is often not compute power but operator dispatch count (pure ATen baseline ~ thousands of dispatches per token). Acceleration has two orthogonal axes:</p>", "a[href=\"#tle-extension-operations\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">TLE extension operations<a class=\"headerlink\" href=\"#tle-extension-operations\" title=\"Link to this heading\">#</a></h2><p>The Arm64 backend registers 6 extension operations covering decode hotspots such as GEMV / normalization / activation / attention, each corresponding to a named tensor operation. Called within <code class=\"docutils literal notranslate\"><span class=\"pre\">@triton.jit</span></code> via <code class=\"docutils literal notranslate\"><span class=\"pre\">triton.language.extra.cpu.tle_ops</span></code>.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
